create function pg_temp.signal_input(k text default 'm1',rev integer default 1,s uuid default '51c03000-0000-4000-8000-000000000001',t uuid default '51c02000-0000-4000-8000-000000000001',kind_value text default 'MESSAGE') returns text language sql as $$
select jsonb_build_object('version',1,'mode','SYNTHETIC','tenant_id',t,'source_id',s,'message_key',k,'revision',rev,'kind',kind_value,'observed_at','2026-10-23T18:00:00Z','published_at',null,'reply_to',null,'original_text',case when kind_value in ('DELETE','RESTRICTED','UNAVAILABLE') then null else 'BUY XAUUSD LIMIT 2700.010 SL 2690.000 TP 2720.10' end,'attachments','[]'::jsonb,'interpretation',case when kind_value in ('DELETE','RESTRICTED','UNAVAILABLE') then 'null'::jsonb else '{"action":"OPEN","direction":"BUY","symbol":"XAUUSD","order_type":"LIMIT","entry":["2700.010"],"stop_loss":"2690.000","take_profits":["2720.10"]}'::jsonb end)::text;
$$;
